const paths=["/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/receipts/1971.txt","/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/swap_log.txt","/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/17.csv"];
const results=await Promise.allSettled(paths.map(file_path=>tools.Read({file_path})));
for(let i=0;i<results.length;i++){const r=results[i];text("## "+paths[i]);if(r.status==="fulfilled"){if(i===2 && typeof r.value==="string"){const lines=r.value.split("\n");text({header:lines[0],line_count:lines.length});text(lines.filter(l=>/^20,/.test(l)).join("\n"));}else text(r.value);}else text(String(r.reason));}

const raw=await tools.Read({file_path:"/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/17.csv"});
if(typeof raw!=="string") throw Error("Expected CSV text");
const lines=raw.trim().split("\n");
const t=Date.parse("2026-07-23T21:23:36Z");
const rad=d=>d*Math.PI/180;
const records=lines.slice(1).map(line=>{const [truck,at,lat,lon,engine,odo]=line.split(",");const a=Math.sin(rad(Number(lat)-29.6805)/2)**2+Math.cos(rad(29.6805))*Math.cos(rad(Number(lat)))*Math.sin(rad(Number(lon)+97.6475)/2)**2;return {line,truck,at,dist_m:6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)),minutes_from_transaction:(Date.parse(at)-t)/60000};});
const inWindow=records.filter(r=>Math.abs(r.minutes_from_transaction)<=10);
const bracketing=records.filter(r=>Math.abs(r.minutes_from_transaction)<=60).sort((a,b)=>a.dist_m-b.dist_m);
const near=records.filter(r=>r.dist_m<=3000);
text({records:records.length,trucks:new Set(records.map(r=>r.truck)).size,pings_in_requested_window:inWindow.length,within_3000m_all_day:near,nearest_within_60_minutes:bracketing.slice(0,12)});
